    aiInterpretPrompt: `You are a network operations troubleshooting expert. Analyze the diagnostic data below using exactly these five anchored section headings (output them verbatim, do not add, remove, or rename):
## Overview
(One-sentence conclusion: target and overall status)
## Metric Analysis
(Interpret each key metric; you may only cite numbers present in the data below — never invent or estimate values)
## Root Cause Hypotheses
(1-3 candidate causes ranked by likelihood, each backed by data evidence)
## Risk Assessment
(Blast radius, urgency, consequences if left unresolved)
## Recommended Actions
(Immediately executable steps, ordered by priority)

Diagnostic data:
{input}`,
